require '../../config/db.php'; $id = filter_input(INPUT_GET, 'id', FILTER_VALIDATE_INT); if (!$id) { header('Location: index.php?success=Invalid category selected.'); exit; } $statement = mysqli_prepare($conn, 'SELECT * FROM categories WHERE id = ?'); mysqli_stmt_bind_param($statement, 'i', $id); mysqli_stmt_execute($statement); $category = mysqli_fetch_assoc(mysqli_stmt_get_result($statement)); if (!$category) { header('Location: index.php?success=Category not found.'); exit; } include '../../includes/header.php'; include '../../includes/sidebar.php';
?>
<div class="card shadow"><div class="card-header"><h3>Category Details</h3></div><div class="card-body"><table class="table table-bordered mb-4"><tr><th width="200">Category</th><td><?= htmlspecialchars($category['category_name'], ENT_QUOTES, 'UTF-8'); ?></td></tr><tr><th>Description</th><td><?= nl2br(htmlspecialchars($category['description'] ?? '', ENT_QUOTES, 'UTF-8')); ?></td></tr><tr><th>Status</th><td><?= $category['is_active'] ? 'Active' : 'Inactive'; ?></td></tr><tr><th>Created At</th><td><?= date('d M Y', strtotime($category['created_at'])); ?></td></tr></table><a href="index.php" class="btn btn-secondary">Back</a></div></div><?php include '../../includes/footer.php'; ?>
